{
  "title": "Tuning panel",
  "description": "Change these while you play: the game picks them up straight away.",
  "width": 900,
  "height": 84,
  "controls": [
    { "type": "slider", "label": "Gravity", "bind": "gc_gravity", "default": 1, "min": 0.5, "max": 2, "step": 0.1, "precision": 1, "suffix": "×", "x": 0, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Engine power", "bind": "gc_thrust", "default": 1, "min": 0.5, "max": 2, "step": 0.1, "precision": 1, "suffix": "×", "x": 182, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Fuel tank", "bind": "gc_fuel", "default": 100, "min": 40, "max": 200, "step": 10, "x": 364, "y": 0, "width": 170, "height": 64 },
    { "type": "slider", "label": "Planets", "bind": "gc_planets", "default": 4, "min": 3, "max": 6, "step": 1, "x": 546, "y": 0, "width": 170, "height": 64 },
    { "type": "readout", "label": "Best score", "bind": "gc_best", "x": 728, "y": 0, "width": 172, "height": 64 }
  ]
}
